userscript.function:

		sUtils.connector.api('service',{
            target:{
                name:"sepoa.svc.admin.AD_050",
                action:"getPasswordPolicy"
            }
        }).then((res)=>{
            if(res.status == 1){
                $share.policy = res.result[0];
                console.log($share.policy)
            }
        });


	if(!formObj.validate()) {
		Alert(sUtils.cache.text.get('AD_380.MESSAGE_PASSWORD_NOT_INPUT'));
		return;
	}

	if(!checkPassPolicy()) {
		Alert($share.msgStack.join("<br/>"));
		return;
	}

	Confirm(sUtils.cache.text.get("MESSAGE.1018"), function(result) {
        if (result) {
        	dataOutput.setValue('HOUSE_CODE', Sepoa.info['HOUSE_CODE'], true);

            doServiceAjax('sepoa.svc.admin.AD_050', 'TRANSACTION', 'doChangePassword', null, function(obj) {
                if (obj.status != 1) {
                    Alert(sUtils.cache.text.get(`AD_051.MESSAGE_${sUtils.string.lpad(obj.status, 4, '0')}`)+`[${obj.status}]`);
                    return;
                }

                Alert(sUtils.cache.text.get('MESSAGE.0001') + '<br/>' + sUtils.cache.text.get('AD_380.MESSAGE_LOGIN_WITH_CHANGED_PASSWORD'), function() {
                	doClose();
                });
            });
        }
    }, false);


const passOrg    = $share.form.getValue("NEW_PASSWORD_1");
const passRepeat = $share.form.getValue("NEW_PASSWORD_2");

$share.msgStack = [];

if(passOrg != passRepeat){
    $share.msgStack.push(`<span>${sUtils.cache.text.get('AD_051_2.MESSAGE_SAME_INPUT')}</span>`);
}
if($share.policy.lengthMin > passOrg.length){
    $share.msgStack.push(`<span>${sUtils.string.dataReplacer(sUtils.cache.text.get('AD_051_2.MESSAGE_POLICY_LENGTH_MIN'), $share.policy)}</span>`);
}

if($share.policy.lengthMax < passOrg.length){
    $share.msgStack.push(`<span>${sUtils.string.dataReplacer(sUtils.cache.text.get('AD_051_2.MESSAGE_POLICY_LENGTH_MAX'), $share.policy)}</span>`);
}

if($share.policy.inSpecial && passOrg.match(/^[0-9|a-z|A-Z]*$/g)){
    $share.msgStack.push(`<span>${sUtils.cache.text.get('AD_051_2.MESSAGE_POLICY_SPECIAL')}</span>`);
}

if($share.policy.inUpper && !passOrg.match(/^.*[A-Z].*$/g)){
    $share.msgStack.push(`<span>${sUtils.cache.text.get('AD_051_2.MESSAGE_POLICY_UPPER')}</span>`);
}

if($share.policy.inLower && !passOrg.match(/^.*[a-z].*$/g)){
    $share.msgStack.push(`<span>${sUtils.cache.text.get('AD_051_2.MESSAGE_POLICY_LOWER')}</span>`);
}

if($share.policy.inNumber && !passOrg.match(/^.*[0-9].*$/g)){
    $share.msgStack.push(`<span>${sUtils.cache.text.get('AD_051_2.MESSAGE_POLICY_NUMBER')}</span>`);
}

if($share.msgStack.length > 0) {
	$share.msgStack.splice(0, 0, `<span class="title">${sUtils.cache.text.get('AD_051_2.MESSAGE_POLICY_FAIL')}</span>`);
	return false;
} else {
	return true;
}
